const r = await Promise.allSettled([
  tools.exec_command({cmd:"ls -la .codex-role-output && cat .codex-role-output/checkpoint.md","workdir":"/app","yield_time_ms":10000,"max_output_tokens":2000}),
  tools.exec_command({cmd:"git status --short && find . -name AGENTS.md -print","workdir":"/app","yield_time_ms":10000,"max_output_tokens":2000}),
  tools.exec_command({cmd:"ls","workdir":"/app","yield_time_ms":10000,"max_output_tokens":2000})
]); r.forEach((x,i)=>text(JSON.stringify({i,result:x.status==="fulfilled"?x.value.output:String(x.reason)})));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"grep -RIn --exclude-dir=node_modules --exclude-dir=build -E 'dropup|category-selector|categorySelector' public src | head -150","workdir":"/app","yield_time_ms":10000,"max_output_tokens":8000}),
  tools.exec_command({cmd:"find public src -iname '*merge*' -o -iname '*fork*' -o -iname '*move*' -o -iname '*recent*chat*' -o -iname '*users*' | head -180","workdir":"/app","yield_time_ms":10000,"max_output_tokens":7000}),
  tools.exec_command({cmd:"grep -RIn --exclude-dir=node_modules --exclude-dir=build -E 'recent.*rooms|recent.*room|room.*recent' public/templates public/src | head -150","workdir":"/app","yield_time_ms":10000,"max_output_tokens":6000})
]); r.forEach((x,i)=>text(JSON.stringify({i,result:x.status==="fulfilled"?x.value.output:String(x.reason)})));

